  if(view==='list'||both)renderList();else renderMeta();
  if(view==='week'||both)renderWeek();
  if(view==='month')renderMonth();
  if(view==='focus')renderFocus();
  if(view==='notes')renderNotes();
  navOn();
  $('#main').classList.toggle('board',view==='list'||view==='week');
